// Package payments charges invoices through the payment gateway.
package payments

import (
	"context"
	"errors"
	"fmt"

	"example.com/tally/internal/billing"
	"example.com/tally/internal/clock"
	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// ChargeRequest asks the gateway to take money from a payment method.
type ChargeRequest struct {
	Amount        int64 // minor units
	Currency      money.Currency
	PaymentMethod string // "pm_..."
	Description   string
}

// ChargeResult is a successful charge.
type ChargeResult struct {
	Ref string // the gateway's reference, "ch_..."
}

// Gateway is the payment processor.
type Gateway interface {
	Charge(ctx context.Context, req ChargeRequest) (ChargeResult, error)
}

// DeclineError is a charge the card's issuer refused. Nothing was taken.
type DeclineError struct {
	Code string // for example "card_declined", "insufficient_funds"
}

func (e *DeclineError) Error() string { return "card declined: " + e.Code }

// Errors.
var (
	// ErrUnavailable means the gateway could not be reached or failed; nothing was taken and the charge may be retried.
	ErrUnavailable     = errors.New("payment gateway unavailable")
	ErrAlreadyPaid     = errors.New("the invoice is already paid")
	ErrInvoiceVoid     = errors.New("the invoice is void")
	ErrNoPaymentMethod = errors.New("no payment method to charge")
)

// Publisher sends events to the organization's webhook endpoints (webhooks.Service).
type Publisher interface {
	Publish(ctx context.Context, orgID, eventType string, data any) error
}

// Service pays invoices.
type Service struct {
	Store     *store.Store
	Gateway   Gateway
	Clock     clock.Clock
	Publisher Publisher // nil: no events
}

// Pay charges an open invoice's total to paymentMethod, or to the customer's default payment method when it is empty, and
// marks the invoice paid. An invoice whose total is zero or less is marked paid without a charge. A declined charge is
// recorded as a failed payment and returned as a *DeclineError; when the gateway is unavailable nothing is recorded and the
// error wraps ErrUnavailable.
func (s *Service) Pay(ctx context.Context, orgID, invoiceID, paymentMethod string) (store.Invoice, store.Payment, error) {
	inv, ok := s.Store.Invoice(orgID, invoiceID)
	if !ok {
		return store.Invoice{}, store.Payment{}, store.ErrNotFound
	}
	switch inv.Status {
	case store.InvoicePaid:
		return inv, store.Payment{}, ErrAlreadyPaid
	case store.InvoiceVoid:
		return inv, store.Payment{}, ErrInvoiceVoid
	}
	total := billing.Compute(inv).Total
	if total <= 0 {
		inv, err := s.markPaid(ctx, inv, store.Payment{})
		return inv, store.Payment{}, err
	}
	if paymentMethod == "" {
		if c, ok := s.Store.Customer(orgID, inv.CustomerID); ok {
			paymentMethod = c.DefaultPaymentMethod
		}
	}
	if paymentMethod == "" {
		return inv, store.Payment{}, ErrNoPaymentMethod
	}
	res, err := s.Gateway.Charge(ctx, ChargeRequest{Amount: total, Currency: inv.Currency, PaymentMethod: paymentMethod, Description: "Invoice " + inv.ID})
	var decline *DeclineError
	switch {
	case errors.As(err, &decline):
		p, perr := s.Store.CreatePayment(store.Payment{OrgID: orgID, InvoiceID: inv.ID, Amount: total, Currency: inv.Currency, Status: store.PaymentFailed, FailureCode: decline.Code}, s.Clock.Now())
		if perr != nil {
			return inv, store.Payment{}, perr
		}
		s.publish(ctx, orgID, "invoice.payment_failed", map[string]any{"invoice_id": inv.ID, "payment_id": p.ID, "failure_code": decline.Code})
		return inv, p, err
	case err != nil:
		if errors.Is(err, ErrUnavailable) {
			return inv, store.Payment{}, err
		}
		return inv, store.Payment{}, fmt.Errorf("%w: %v", ErrUnavailable, err)
	}
	p, err := s.Store.CreatePayment(store.Payment{OrgID: orgID, InvoiceID: inv.ID, Amount: total, Currency: inv.Currency, Status: store.PaymentSucceeded, GatewayRef: res.Ref}, s.Clock.Now())
	if err != nil {
		return inv, store.Payment{}, err
	}
	inv, err = s.markPaid(ctx, inv, p)
	return inv, p, err
}

func (s *Service) markPaid(ctx context.Context, inv store.Invoice, p store.Payment) (store.Invoice, error) {
	now := s.Clock.Now()
	inv, err := s.Store.UpdateInvoice(inv.OrgID, inv.ID, func(i *store.Invoice) error {
		i.Status = store.InvoicePaid
		i.PaidAt = &now
		return nil
	})
// Package subscriptions runs subscriptions: starting them with their first invoice, changing and canceling them, and
// renewing them when a billing period ends.
package subscriptions

import (
	"context"
	"errors"
	"fmt"
	"time"

	"example.com/tally/internal/billing"
	"example.com/tally/internal/clock"
	"example.com/tally/internal/payments"
	"example.com/tally/internal/store"
)

// Errors.
var (
	ErrPlanInactive = errors.New("the plan is not active")
	ErrCanceled     = errors.New("the subscription is canceled")
)

// Service runs subscriptions.
type Service struct {
	Store     *store.Store
	Payments  *payments.Service
	Clock     clock.Clock
	Publisher payments.Publisher // nil: no events
}

// CreateInput is a new subscription.
type CreateInput struct {
	CustomerID      string
	PlanID          string
	Quantity        int // 0 means 1
	DiscountPercent int
}

// Create starts a subscription now. With a plan that has a trial, the subscription is trialing until the trial ends, and
// its first period starts then. Otherwise its first period starts now; for a licensed plan that period is invoiced at once
// and charged to the customer's default payment method, if it has one (a declined charge makes the subscription past due).
func (s *Service) Create(ctx context.Context, orgID string, in CreateInput) (store.Subscription, error) {
	plan, ok := s.Store.Plan(orgID, in.PlanID)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	if !plan.Active {
		return store.Subscription{}, ErrPlanInactive
	}
	if in.Quantity == 0 {
		in.Quantity = 1
	}
	now := s.Clock.Now()
	sub := store.Subscription{OrgID: orgID, CustomerID: in.CustomerID, PlanID: plan.ID, Quantity: in.Quantity, DiscountPercent: in.DiscountPercent,
		StartedAt: now, CurrentPeriodStart: now}
	if plan.TrialDays > 0 {
		end := now.AddDate(0, 0, plan.TrialDays)
		sub.Status, sub.TrialEnd, sub.CurrentPeriodEnd = store.Trialing, &end, end
	} else {
		sub.Status, sub.CurrentPeriodEnd = store.Active, billing.AddInterval(now, plan.Interval)
	}
	sub, err := s.Store.CreateSubscription(sub, now)
	if err != nil {
		return store.Subscription{}, err
	}
	s.publish(ctx, orgID, "subscription.created", sub)
	if sub.Status == store.Active && plan.UsageType == store.Licensed {
		paid, err := s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
		if err != nil {
			return sub, err
		}
		if !paid {
			if sub, err = s.setStatus(ctx, sub, store.PastDue); err != nil {
				return sub, err
			}
		}
	}
	return sub, nil
}

	if err != nil {
		return err
	}
	s.publish(ctx, sub.OrgID, "subscription.updated", sub)
	return nil
}

// invoicePeriod invoices one period of a subscription and charges the invoice to the customer's default payment method.
// It reports false when the charge was declined. An invoice that needs no charge is marked paid; one whose customer has no
// payment method stays open and counts as paid here (it is paid by hand).
func (s *Service) invoicePeriod(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (bool, error) {
	var lines []store.Line
	period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
	switch plan.UsageType {
	case store.Licensed:
		if plan.UnitAmount > 0 {
			lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
		}
	case store.Metered:
		if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
			lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
		}
	}
	ps, pe := start, end
	inv, err := s.Store.CreateInvoice(store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: plan.Currency,
		Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}, s.Clock.Now())
	if err != nil {
		return false, err
	}
	s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
	_, _, err = s.Payments.Pay(ctx, sub.OrgID, inv.ID, "")
	var decline *payments.DeclineError
	switch {
	case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
		return true, nil
	case errors.As(err, &decline):
		return false, nil
	default:
		return false, err
	}
}

func (s *Service) setStatus(ctx context.Context, sub store.Subscription, st store.SubStatus) (store.Subscription, error) {
	sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
		x.Status = st
		return nil
	})
	if err == nil {
		s.publish(ctx, sub.OrgID, "subscription.updated", sub)
	}
	return sub, err
}

func (s *Service) publish(ctx context.Context, orgID, typ string, data any) {
	if s.Publisher != nil {
		_ = s.Publisher.Publish(ctx, orgID, typ, data)
	}
}

