package store

import (
	"sort"
	"strings"
	"time"
)

// customerRetentionDays is how long a deleted customer can be restored before it is purged.
const customerRetentionDays = 30

// deletedBefore returns the cut-off for deleted customers at now: a customer deleted before it has been deleted for more
// than customerRetentionDays, so it can no longer be restored and PurgeDeletedCustomers removes it.
func deletedBefore(now time.Time) time.Time { return now.UTC().AddDate(0, 0, -customerRetentionDays) }

// CreateCustomer adds a customer to an organization. A customer's email address is unique within the organization,
// ignoring case.
func (s *Store) CreateCustomer(orgID, name, email string, now time.Time) (Customer, error) {
	name, email = strings.TrimSpace(name), strings.TrimSpace(email)
	if name == "" || !validEmail(email) {
		return Customer{}, invalid("a customer needs a name and a valid email address")
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.orgs[orgID]; !ok {
		return Customer{}, ErrNotFound
	}
	key := emailKey{orgID, normEmail(email)}
	if _, ok := s.customersByEmail[key]; ok {
		return Customer{}, ErrEmailTaken
	}
	c := Customer{ID: s.newID("cus"), OrgID: orgID, Name: name, Email: email, CreatedAt: now.UTC()}
	s.customers[c.ID] = c
	s.customersByEmail[key] = c.ID
	return c, nil
}

// Customer returns one of an organization's customers. A deleted customer is not found.
func (s *Store) Customer(orgID, id string) (Customer, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.OrgID != orgID || c.DeletedAt != nil {
		return Customer{}, false
	}
	return copyCustomer(c), true
}

// CustomerWithDeleted returns one of an organization's customers, deleted ones included (for the invoices that name them).
func (s *Store) CustomerWithDeleted(orgID, id string) (Customer, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.OrgID != orgID {
		return Customer{}, false
	}
	return copyCustomer(c), true
}

// CustomerByID returns a live customer of any organization (background jobs and the admin tool).
func (s *Store) CustomerByID(id string) (Customer, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.DeletedAt != nil {
		return Customer{}, false
	}
