func TestSoftDeleteCustomer(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	jane, _ := s.CreateCustomer(a.ID, "Jane Doe", "jane@example.com", t0)
	john, _ := s.CreateCustomer(a.ID, "John Roe", "john@example.com", t0.Add(time.Minute))
	del := t0.Add(time.Hour)
	if err := s.SoftDeleteCustomer(a.ID, jane.ID, del); err != nil {
		t.Fatal(err)
	}
	if err := s.SoftDeleteCustomer(a.ID, jane.ID, del); !errors.Is(err, ErrNotFound) {
		t.Fatalf("deleting twice: %v", err)
	}
	if _, ok := s.Customer(a.ID, jane.ID); ok {
		t.Fatal("deleted customer is still visible")
	}
	if _, ok := s.CustomerByID(jane.ID); ok {
		t.Fatal("deleted customer is still visible by ID")
	}
	if got, ok := s.CustomerWithDeleted(a.ID, jane.ID); !ok || got.DeletedAt == nil || !got.DeletedAt.Equal(del) {
		t.Fatalf("CustomerWithDeleted = %+v, %v", got, ok)
	}
	if got := s.Customers(a.ID); len(got) != 1 || got[0].ID != john.ID {
		t.Fatalf("Customers = %+v", got)
	}
	if got := s.CustomersWithDeleted(a.ID); len(got) != 2 || got[0].ID != jane.ID {
		t.Fatalf("CustomersWithDeleted = %+v", got)
	}
	if got := s.SearchCustomers(a.ID, "jane"); len(got) != 0 {
		t.Fatalf("SearchCustomers finds the deleted customer: %+v", got)
	}
	if _, ok := s.FindCustomerByEmail(a.ID, "jane@example.com"); ok {
		t.Fatal("FindCustomerByEmail finds the deleted customer")
	}
	if _, err := s.UpdateCustomer(a.ID, jane.ID, func(c *Customer) error { c.Name = "Changed"; return nil }); !errors.Is(err, ErrNotFound) {
		t.Fatalf("updating a deleted customer: %v", err)
	}
	if err := s.DeleteCustomer(a.ID, jane.ID); err != nil {
		t.Fatalf("removing a deleted customer outright: %v", err)
	}
	if _, ok := s.CustomerWithDeleted(a.ID, jane.ID); ok {
		t.Fatal("removed customer is still there")
	}

	// Its email address is free again.
	again, err := s.CreateCustomer(a.ID, "Jane Again", "JANE@example.com", t0)
	if err != nil {
		t.Fatalf("email of a deleted customer is not free: %v", err)
	}
	if err := s.SoftDeleteCustomer(a.ID, again.ID, del); err != nil {
		t.Fatal(err)
	}
	if _, err := s.CreateCustomer(a.ID, "Jane Third", "jane@example.com", t0); err != nil {
		t.Fatalf("email of a deleted customer is not free: %v", err)
	}
}

func TestSoftDeleteRefusesActiveSubscriptions(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	c, _ := s.CreateCustomer(a.ID, "Jane", "jane@example.com", t0)
	p, err := s.CreatePlan(Plan{OrgID: a.ID, Name: "Pro", Currency: money.USD, UnitAmount: 100, Interval: Monthly, Active: true}, t0)
	if err != nil {
		t.Fatal(err)
	}
	for _, st := range []SubStatus{Trialing, Active, PastDue} {
		sub, err := s.CreateSubscription(Subscription{OrgID: a.ID, CustomerID: c.ID, PlanID: p.ID, Quantity: 1, Status: st}, t0)
		if err != nil {
			t.Fatal(err)
		}
		if err := s.SoftDeleteCustomer(a.ID, c.ID, t0); !errors.Is(err, ErrActiveSubscriptions) || !errors.Is(err, ErrConflict) {
			t.Fatalf("deleting a customer with a %s subscription: %v", st, err)
		}
		if _, ok := s.Customer(a.ID, c.ID); !ok {
			t.Fatal("refused deletion hid the customer")
		}
		if _, err := s.UpdateSubscription(a.ID, sub.ID, func(x *Subscription) error { x.Status = Canceled; return nil }); err != nil {
			t.Fatal(err)
		}
	}
	if err := s.SoftDeleteCustomer(a.ID, c.ID, t0); err != nil {
		t.Fatalf("deleting a customer whose subscriptions are all canceled: %v", err)
	}
}

func TestDeletedCustomerCannotGetNewInvoicesOrSubscriptions(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	c, _ := s.CreateCustomer(a.ID, "Jane", "jane@example.com", t0)
	p, _ := s.CreatePlan(Plan{OrgID: a.ID, Name: "Pro", Currency: money.USD, UnitAmount: 100, Interval: Monthly, Active: true}, t0)
	if err := s.SoftDeleteCustomer(a.ID, c.ID, t0); err != nil {
		t.Fatal(err)
	}
	inv := Invoice{OrgID: a.ID, CustomerID: c.ID, Currency: money.USD, Lines: []Line{{Description: "x", Quantity: 1, UnitAmount: 100}}}
	if _, err := s.CreateInvoice(inv, t0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("invoice for a deleted customer: %v", err)
	}
	if _, err := s.CreateSubscription(Subscription{OrgID: a.ID, CustomerID: c.ID, PlanID: p.ID, Quantity: 1, Status: Active}, t0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("subscription for a deleted customer: %v", err)
	}
}

func TestRestoreCustomer(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	c, _ := s.CreateCustomer(a.ID, "Jane", "jane@example.com", t0)
	if _, err := s.RestoreCustomer(a.ID, c.ID, t0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("restoring a customer that is not deleted: %v", err)
	}
	if err := s.SoftDeleteCustomer(a.ID, c.ID, t0); err != nil {
		t.Fatal(err)
	}
	if _, err := s.RestoreCustomer(s.newOrgID(t, "B"), c.ID, t0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("restoring through another org: %v", err)
	}
	// Restorable up to 30 days after the deletion, not after.
	if _, err := s.RestoreCustomer(a.ID, c.ID, t0.AddDate(0, 0, 31)); !errors.Is(err, ErrNotFound) {
		t.Fatalf("restoring after 31 days: %v", err)
	}
	if _, err := s.RestoreCustomer(a.ID, c.ID, t0.AddDate(0, 0, 30)); err != nil {
		t.Fatalf("restoring after 30 days: %v", err)
	}
	if got, ok := s.Customer(a.ID, c.ID); !ok || got.DeletedAt != nil {
		t.Fatalf("restored customer = %+v, %v", got, ok)
	}
	if got, ok := s.FindCustomerByEmail(a.ID, "jane@example.com"); !ok || got.ID != c.ID {
		t.Fatalf("restored customer is not found by email: %+v %v", got, ok)
	}

	// Someone else took the address in the meantime.
	if err := s.SoftDeleteCustomer(a.ID, c.ID, t0); err != nil {
		t.Fatal(err)
	}
	other, _ := s.CreateCustomer(a.ID, "Jane Two", "Jane@Example.com", t0)
	if _, err := s.RestoreCustomer(a.ID, c.ID, t0); !errors.Is(err, ErrEmailTaken) {
		t.Fatalf("restoring over another customer's email: %v", err)
	}
	if err := s.SoftDeleteCustomer(a.ID, other.ID, t0); err != nil {
		t.Fatal(err)
	}
	if _, err := s.RestoreCustomer(a.ID, c.ID, t0); err != nil {
		t.Fatalf("restoring once the address is free: %v", err)
	}
}

func TestPurgeDeletedCustomers(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	old, _ := s.CreateCustomer(a.ID, "Old", "old@example.com", t0)
	recent, _ := s.CreateCustomer(a.ID, "Recent", "recent@example.com", t0)
	live, _ := s.CreateCustomer(a.ID, "Live", "live@example.com", t0)
	if err := s.SoftDeleteCustomer(a.ID, old.ID, t0); err != nil {
		t.Fatal(err)
	}
	now := t0.AddDate(0, 0, 40)
	if err := s.SoftDeleteCustomer(a.ID, recent.ID, now.AddDate(0, 0, -5)); err != nil {
		t.Fatal(err)
	}
	if n := s.PurgeDeletedCustomers(now); n != 1 {
		t.Fatalf("PurgeDeletedCustomers removed %d, want 1", n)
	}
	if _, ok := s.CustomerWithDeleted(a.ID, old.ID); ok {
		t.Fatal("purged customer is still there")
	}
	if _, ok := s.CustomerWithDeleted(a.ID, recent.ID); !ok {
		t.Fatal("customer deleted 5 days ago was purged")
	}
	if _, ok := s.Customer(a.ID, live.ID); !ok {
		t.Fatal("live customer was purged")
	}
	if n := s.PurgeDeletedCustomers(now); n != 0 {
		t.Fatalf("second purge removed %d", n)
	}
}

func TestCustomerEmailsArePerOrganization(t *testing.T) {
	s := New()
	a, b := newOrg(t, s, "A"), newOrg(t, s, "B")
	ca, _ := s.CreateCustomer(a.ID, "Jane A", "jane@example.com", t0)
	cb, _ := s.CreateCustomer(b.ID, "Jane B", "jane@example.com", t0.Add(time.Minute))
	if got, ok := s.FindCustomerByEmail(a.ID, "jane@example.com"); !ok || got.ID != ca.ID {
		t.Fatalf("org A finds %+v, %v", got, ok)
	}
	if got, ok := s.FindCustomerByEmail(b.ID, "jane@example.com"); !ok || got.ID != cb.ID {
		t.Fatalf("org B finds %+v, %v", got, ok)
	}
	if err := s.SoftDeleteCustomer(b.ID, cb.ID, t0); err != nil {
		t.Fatal(err)
	}
	if got, ok := s.FindCustomerByEmail(a.ID, "jane@example.com"); !ok || got.ID != ca.ID {
		t.Fatalf("deleting org B's customer hid org A's: %+v, %v", got, ok)
	}
}

func TestSoftDeleteSurvivesSnapshot(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	c, _ := s.CreateCustomer(a.ID, "Jane", "jane@example.com", t0)
	if err := s.SoftDeleteCustomer(a.ID, c.ID, t0); err != nil {
		t.Fatal(err)
	}
	back, err := FromState(s.Export())
	if err != nil {
		t.Fatal(err)
	}
	if _, ok := back.CustomerWithDeleted(a.ID, c.ID); !ok {
		t.Fatal("deleted customer lost in the snapshot")
	}
	if _, ok := back.FindCustomerByEmail(a.ID, "jane@example.com"); ok {
		t.Fatal("deleted customer's email is indexed after the snapshot")
	}
	if _, err := back.CreateCustomer(a.ID, "Jane Again", "jane@example.com", t0); err != nil {
		t.Fatalf("email of a deleted customer is not free after the snapshot: %v", err)
	}
	if _, err := back.RestoreCustomer(a.ID, c.ID, t0); !errors.Is(err, ErrEmailTaken) {
		t.Fatalf("restore after the snapshot: %v", err)
	}
}
